// ❌ Interface 'gorda' — viola ISP
public interface IGameEntity
{
    void TakeDamage(int amount);  // no todo puede recibir daño
    void Move(Vector3 direction); // no todo puede moverse
    void Interact();              // no todo es interactuable
    void PlaySound();             // no todo hace sonido
}

// ✅ Interfaces segregadas — respeta ISP
public interface IDamageable  { void TakeDamage(int amount); }
public interface IMovable     { void Move(Vector3 direction); }
public interface IInteractable{ void Interact(); }

// La roca solo implementa lo que tiene sentido
public class Rock : IDamageable { public void TakeDamage(int a) { ... } }

// El enemigo implementa lo que necesita
public class Goblin : IDamageable, IMovable { ... }

// ❌ Viola DIP — dependencia hardcoded
public class PlayerCombat : MonoBehaviour
{
    private SwordAttack weapon = new SwordAttack(); // acoplado a SwordAttack
    void Update() { if (Input.GetMouseButtonDown(0)) weapon.Attack(); }
}

// ✅ Respeta DIP — depende de abstracción, inyectada desde el Inspector
public interface IWeapon { void Attack(); }

public class PlayerCombat : MonoBehaviour
{
    [SerializeField] private MonoBehaviour weaponBehaviour;
    private IWeapon weapon;

    void Awake() { weapon = weaponBehaviour as IWeapon; }
    void Update() { if (Input.GetMouseButtonDown(0)) weapon?.Attack(); }
}

// SwordAttack y BowAttack son detalles que dependen de la abstracción IWeapon
public class SwordAttack : MonoBehaviour, IWeapon { public void Attack() { ... } }
public class BowAttack   : MonoBehaviour, IWeapon { public void Attack() { ... } }

