public interface IGameEntity
{
    void TakeDamage(int amount);
    void Move(Vector3 direction);
    void Interact();
    void PlaySound();
    void SaveState();
}

public interface IDamageable  { void TakeDamage(int amount); }
public interface IInteractable { void Interact(); }
public interface IMovable     { void Move(Vector3 dir); }

public class Chest : IDamageable, IInteractable
{
    public void TakeDamage(int a) { ... }
    public void Interact()        { ... }
}

public class PlayerCombat : MonoBehaviour
{
    private SwordAttack weapon = new SwordAttack();

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
            weapon.Attack();
    }
}

public class PlayerCombat : MonoBehaviour
{
    [SerializeField] private MonoBehaviour weaponBehaviour;
    private IWeapon weapon;

    void Awake()
    {
        weapon = weaponBehaviour as IWeapon;
    }

    void Update()
    {
        if (Input.GetMouseButtonDown(0)) weapon?.Attack();
    }
}

public interface IEnemy
{
    void Walk();
    void Fly();
    void Swim();
    void TakeDamage(int amount);
    void Shoot();
    void MeleeAttack();
}
public class Goblin : IEnemy
{
    public void Walk()        { ... }
    public void Fly()         { throw new NotImplementedException(); }
    public void Swim()        { throw new NotImplementedException(); }
    public void TakeDamage(int a) { ... }
    public void Shoot()       { throw new NotImplementedException(); }
    public void MeleeAttack() { ... }
}

public interface IWeapon { void Attack(); }

public class SwordAttack : MonoBehaviour, IWeapon
{
    public void Attack() { DealSlashDamage(); }
}

public class BowAttack : MonoBehaviour, IWeapon
{
    public void Attack() { ShootArrow(); }
}

